import {esc,fmt} from './tank-visuals.js';
import {nozzleHostLabel,nozzleHasConflict} from './tank-nozzles.js';
export function nozzleLayoutSketch(r,{selected='',interactive=false,compact=false}={}){
  if(!r?.valid)return '<p class="tank-note">先修正桶槽尺寸，再選管嘴位置。</p>';
  const current=r.nozzlePlan.items.find(n=>n.id===selected)??r.input.nozzles?.find(n=>n.id===selected),host=current?.host??'shell',cx=335,cy=145,rad=65,horizontal=r.orientation==='horizontal';
  const attrs=(id,label)=>interactive?`data-nozzle-select="${id}" role="button" tabindex="0" aria-label="選取 ${id} ${esc(label)}"`:'';
  const markers=r.nozzlePlan.items.filter(n=>n.host===host).map(n=>{const a=n.angle*Math.PI/180,rr=n.host==='shell'?rad:n.radius/(r.di/2)*rad,x=cx+rr*Math.sin(a),y=cy-rr*Math.cos(a),picked=n.id===selected,bad=nozzleHasConflict(n);return `<g ${attrs(n.id,n.name)}>${bad?`<circle cx="${x}" cy="${y}" r="15" fill="none" stroke="#c0392b" stroke-width="2" stroke-dasharray="3 2"/>`:''}<circle cx="${x}" cy="${y}" r="${picked?10:7}" fill="${picked?'#c88931':bad?'#c0392b':'#4f92af'}" stroke="#fff" stroke-width="2"/><text x="${x+13}" y="${y+5}" font-size="14" fill="#24526c">${n.id}</text></g>`;}).join('');
  const dots=r.nozzlePlan.items.filter(n=>n.host==='shell').map(n=>{const y=250-n.height/r.bodyHeight*190,bad=nozzleHasConflict(n);return `<g ${attrs(n.id,n.name)}>${bad?`<circle cx="125" cy="${y}" r="15" fill="none" stroke="#c0392b" stroke-width="2" stroke-dasharray="3 2"/>`:''}<circle cx="125" cy="${y}" r="${n.id===selected?10:7}" fill="${n.id===selected?'#c88931':bad?'#c0392b':'#4f92af'}" stroke="#fff" stroke-width="2"/><text x="145" y="${y+4}" font-size="14" fill="#24526c">${n.id} · ${fmt(n.height)} mm</text></g>`;}).join('');
  return `<svg viewBox="${compact?'0 0 280 650':'0 0 480 325'}" role="${interactive?'group':'img'}" aria-label="管嘴位置：筒身高度圖與俯視方位圖"><g><text x="55" y="24" font-size="14" fill="#24526c">${horizontal?'筒身位置（A 端起）':'筒身高度'}</text><rect x="55" y="60" width="140" height="190" rx="8" fill="#d1e5ed" stroke="#547d91" ${interactive&&host==='shell'?'data-nozzle-position="height" role="button" tabindex="0" aria-label="點筒身圖調管嘴高度"':''}/><path d="M125 48V260" stroke="#91acbb" stroke-dasharray="4 4" pointer-events="none"/>${dots}<text x="55" y="274" font-size="12" fill="#617086">${horizontal?'A 端筒身板邊':'筒身板下緣'} = 0 mm</text><text x="55" y="295" font-size="12" fill="#617086">筒身板${horizontal?'長':'高'} ${fmt(r.bodyHeight)} mm</text></g><g transform="${compact?'translate(-210 325)':'translate(0 0)'}"><text x="266" y="24" font-size="14" fill="#24526c">${host==='shell'?(horizontal?'筒壁端視方位（由 A 端看）':'筒壁俯視方位'):esc(nozzleHostLabel(host,r))}</text><circle cx="${cx}" cy="${cy}" r="${rad}" fill="#eef5f8" stroke="#547d91" stroke-width="2" ${interactive?`data-nozzle-position="${host==='shell'?'angle':'end'}" role="button" tabindex="0" aria-label="${host==='shell'?'點圓周調方位角':'點圓板調管嘴偏心及方位'}"`:''}/><path d="M335 60V230M250 145H420" stroke="#c5d5de" stroke-dasharray="4 4" pointer-events="none"/><text x="335" y="56" text-anchor="middle" font-size="13" fill="#93652d">${horizontal?'0° 頂部':'0° 基準'}</text><text x="424" y="149" font-size="12" fill="#617086">90°</text><text x="335" y="247" text-anchor="middle" font-size="12" fill="#617086">180°</text><text x="234" y="149" font-size="12" fill="#617086">270°</text>${markers}<text x="257" y="275" font-size="12" fill="#617086">${horizontal?'由 A 端看順時針':'俯視順時針'} · ${Number(r.input.seamStart)?'第 1 圈起縫 '+fmt(Number(r.input.seamStart))+'°':'第 1 圈起縫為 0°'}</text><text x="257" y="295" font-size="12" fill="#617086">${interactive?'點圖粗調，下方可精確填數值':'位置示意，圖面非 1:1'}</text></g></svg>`;
}
export function nozzleSectionSketch(n){return flangeMeasurementSketch(n);}

export function flangeMeasurementSketch(n,{interactive=false}={}){
  const wn=n.end==='wn',so=n.end==='so',flange=n.end!=='bare',rf=n.flangeFacing==='RF',plateFace=rf?405:412,end=wn?255:so&&Number(n.soSetback)>0?388:412;
  const at=(field,label,markup)=>`<g ${interactive?`data-flange-field="${field}" role="button" tabindex="0" aria-label="修改 ${esc(label)}"`:''}>${markup}</g>`;
  const dimension=(field,label,x1,x2,y,text,color='#93652d')=>{const center=(x1+x2)/2,width=Math.max(x2-x1+16,text.length*8+16);return at(field,label,`${interactive?`<rect x="${center-width/2}" y="${y-30}" width="${width}" height="44" fill="transparent"/>`:''}<path d="M${x1} ${y-5}V${y+5}M${x1} ${y}H${x2}M${x2} ${y-5}V${y+5}" stroke="${color}"/><text x="${center}" y="${y-10}" text-anchor="middle" font-size="14" fill="${color}">${esc(text)}</text>`);};
  return `<svg viewBox="0 0 500 310" role="${interactive?'group':'img'}" aria-label="法蘭接法與量測基準${interactive?'，點尺寸回到輸入欄位':''}"><rect x="55" y="102" width="17" height="114" fill="#bed7e1" stroke="#547d91"/><path d="M54 143H${end}V177H54" fill="#abcddc" stroke="#416d82"/>${flange?`<path d="M${wn?272:332} 143L375 127V102H${plateFace}V216H375V191L${wn?272:332} 177Z" fill="#e2caa6" stroke="#a07b45"/>${rf?'<rect x="405" y="123" width="7" height="74" fill="#cfb58a" stroke="#a07b45"/>':''}`:''}${so?`<path d="M54 143H${end}V177H54" fill="#abcddc" stroke="#416d82"/>`:''}<path d="M54 153H${wn?255:end}V167H54" fill="white" stroke="#7d9bad"/>${wn?'<path d="M272 153H412V167H272" fill="white" stroke="#7d9bad"/>':so&&Number(n.soSetback)>0?'<path d="M388 143H412V177H388" fill="white" stroke="#7d9bad"/>':''}<path d="M28 160H466" stroke="#91acbb" stroke-dasharray="4 4"/><path d="M72 87V235M412 87V235" stroke="#c5d5de" stroke-dasharray="3 3"/>${dimension('projection','外壁到密封面／管端',72,412,81,'外伸 A '+fmt(n.projection,2)+' mm','#206c89')}${flange?dimension('flangeLength','法蘭占長',wn?272:332,412,35,'L '+fmt(n.flangeLength,2)+' mm'):''}${flange?at('flangeOD','法蘭外徑',`${interactive?'<rect x="427" y="73" width="66" height="150" fill="transparent"/>':''}<path d="M442 102H454M448 102V216M442 216H454" stroke="#93652d"/><text x="448" y="95" text-anchor="middle" font-size="13" fill="#93652d">D ${fmt(n.flangeOD,2)}</text>`):''}${wn?dimension('weldGap','對焊端間隙',255,272,244,'間隙 g '+fmt(n.weldGap,2)+' mm'):so?dimension('soSetback','管端退縮',end,412,260,'退縮 s '+fmt(n.soSetback,2)+' mm'):''}<text x="55" y="238" font-size="12" fill="#617086">槽壁</text><text x="408" y="281" text-anchor="middle" font-size="12" fill="#617086">${flange?'密封面':'管端面'}</text><text x="25" y="303" font-size="12" fill="#617086">量測示意，非比例；${interactive?'點尺寸可修改':'尺寸依實物／供應商覆核'}</text></svg>`;
}
